from pathlib import Path

def replace_once(path, old, new):
    p = Path(path)
    text = p.read_text()
    if text.count(old) != 1:
        raise SystemExit(f'{path}: expected one match, got {text.count(old)}')
    p.write_text(text.replace(old, new, 1))

Path('apps/mobile/src/features/plugs/data/blePlugReadError.ts').write_text("""import type { Result, ShellyClientError, ShellyErrorKind } from '@lcl/shelly-client';
import { shellyResultErrorMessage } from '../../../platform/shellyResult.js';

export class BlePlugReadError extends Error {
  readonly kind: ShellyErrorKind;
  readonly retryable: boolean;

  constructor(error: ShellyClientError) {
    super(shellyResultErrorMessage({ ok: false, error }));
    this.name = 'BlePlugReadError';
    this.kind = error.kind;
    this.retryable = error.retryable;
  }
}

export const isRecoverableBlePlugReadError = (
  error: unknown
): error is BlePlugReadError =>
  error instanceof BlePlugReadError &&
  error.retryable &&
  (error.kind === 'shelly-offline' || error.kind === 'timeout');

export const unwrapBlePlugReadResult = <T>(
  result: Result<T, ShellyClientError>
): T => {
  if (!result.ok) throw new BlePlugReadError(result.error);
  return result.value;
};
""")

Path('apps/mobile/src/features/plugs/data/blePlugRuntime.ts').write_text("""import {
  RpcShellyClient,
  type ShellyClient,
  type ShellyRpcTransport,
  type ShellyStatus
} from '@lcl/shelly-client';
import { createShellyBleTransport } from '../../../platform/shellyBleTransport.js';
import { unwrapShellyResult } from '../../../platform/shellyResult.js';
import { unwrapBlePlugReadResult } from './blePlugReadError.js';
import type { SavedBlePlug } from './savedBlePlug.js';

export type BlePlugRuntimeStatus = Pick<ShellyStatus, 'relayOn' | 'telemetry' | 'clock'>;

type BlePlugRuntimeClient = Pick<
  ShellyClient,
  'getStatus' | 'setRelayOn' | 'setRelayOff'
>;

type DisposableShellyRpcTransport = ShellyRpcTransport & {
  disconnect(): Promise<void>;
};

export type BlePlugRuntimeDependencies = {
  createTransport(deviceId: string): DisposableShellyRpcTransport;
  createClient(transport: ShellyRpcTransport): BlePlugRuntimeClient;
};

const defaultDependencies: BlePlugRuntimeDependencies = {
  createTransport: (deviceId) => createShellyBleTransport(deviceId),
  createClient: (transport) => new RpcShellyClient(transport)
};

const operationCompletionByDeviceId = new Map<string, Promise<void>>();

const serializeBlePlugOperation = async <T>(
  deviceId: string,
  work: () => Promise<T>
): Promise<T> => {
  const previous = operationCompletionByDeviceId.get(deviceId) ?? Promise.resolve();
  let release!: () => void;
  const completion = new Promise<void>((resolve) => {
    release = resolve;
  });
  operationCompletionByDeviceId.set(deviceId, completion);

  await previous;
  try {
    return await work();
  } finally {
    release();
    if (operationCompletionByDeviceId.get(deviceId) === completion) {
      operationCompletionByDeviceId.delete(deviceId);
    }
  }
};

const withBlePlugClient = async <T>(
  plug: Pick<SavedBlePlug, 'bleDeviceId'>,
  work: (client: BlePlugRuntimeClient) => Promise<T>,
  dependencies: BlePlugRuntimeDependencies
): Promise<T> =>
  serializeBlePlugOperation(plug.bleDeviceId, async () => {
    const transport = dependencies.createTransport(plug.bleDeviceId);
    try {
      return await work(dependencies.createClient(transport));
    } finally {
      await transport.disconnect().catch(() => undefined);
    }
  });

export const readBlePlugRuntimeStatus = async (
  plug: Pick<SavedBlePlug, 'bleDeviceId'>,
  dependencies: BlePlugRuntimeDependencies = defaultDependencies
): Promise<BlePlugRuntimeStatus> =>
  withBlePlugClient(
    plug,
    async (client) => {
      const value = unwrapBlePlugReadResult(await client.getStatus());
      return {
        relayOn: value.relayOn,
        telemetry: value.telemetry,
        clock: value.clock
      };
    },
    dependencies
  );

export const setBlePlugRelay = async (
  plug: Pick<SavedBlePlug, 'bleDeviceId'>,
  relayOn: boolean,
  dependencies: BlePlugRuntimeDependencies = defaultDependencies
): Promise<void> => {
  await withBlePlugClient(
    plug,
    async (client) => {
      unwrapShellyResult(
        relayOn ? await client.setRelayOn() : await client.setRelayOff()
      );
    },
    dependencies
  );
};
""")

Path('apps/mobile/src/features/plugs/flows/recoverSavedBlePlugLocator.ts').write_text("""import { Capacitor } from '@capacitor/core';
import { CapacitorBleScanner } from '@lcl/ble-core';
import { normalizeShellyDeviceId } from '@lcl/shelly-client';
import type {
  PlugBleAdvertisement,
  VerifiedPlugBleCandidate
} from '../data/plugBleOnboarding.js';
import type { SavedBlePlug } from '../data/savedBlePlug.js';
import { inspectPlugBleCandidate } from './inspectPlugBleCandidate.js';
import {
  DEFAULT_PLUG_BLE_SCAN_TIMEOUT_MS,
  scanPlugBleCandidates
} from './scanPlugBleCandidates.js';

export const PLUG_BLE_LOCATOR_RECOVERY_MAX_CANDIDATES = 6;

export type SavedBlePlugLocatorRecoveryOptions = {
  persistLocator(physicalId: string, bleDeviceId: string): void;
};

export type SavedBlePlugLocatorRecoveryDependencies = {
  scanCandidates?(): Promise<PlugBleAdvertisement[]>;
  inspectCandidate?(candidate: PlugBleAdvertisement): Promise<VerifiedPlugBleCandidate>;
};

type RecoveryScanCandidates = NonNullable<
  SavedBlePlugLocatorRecoveryDependencies['scanCandidates']
>;
type RecoveryInspectCandidate = NonNullable<
  SavedBlePlugLocatorRecoveryDependencies['inspectCandidate']
>;

const recoveryByPhysicalId = new Map<string, Promise<string>>();

const defaultScanCandidates: RecoveryScanCandidates = async () =>
  scanPlugBleCandidates({
    scanner: new CapacitorBleScanner({ platform: Capacitor.getPlatform() }),
    timeoutMs: DEFAULT_PLUG_BLE_SCAN_TIMEOUT_MS
  });

const defaultInspectCandidate: RecoveryInspectCandidate = (candidate) =>
  inspectPlugBleCandidate(candidate, { includePreview: false });

const prioritizeCandidates = (
  plug: SavedBlePlug,
  candidates: readonly PlugBleAdvertisement[]
): PlugBleAdvertisement[] => {
  const savedAdvertisementName = plug.advertisementName.trim().toLowerCase();
  return candidates
    .map((candidate, index) => ({
      candidate,
      index,
      nameMatch:
        savedAdvertisementName.length > 0 &&
        candidate.name.trim().toLowerCase() === savedAdvertisementName
    }))
    .sort((left, right) => {
      const namePriority = Number(right.nameMatch) - Number(left.nameMatch);
      if (namePriority !== 0) return namePriority;
      const rssiPriority = (right.candidate.rssi ?? -999) - (left.candidate.rssi ?? -999);
      if (rssiPriority !== 0) return rssiPriority;
      return left.index - right.index;
    })
    .slice(0, PLUG_BLE_LOCATOR_RECOVERY_MAX_CANDIDATES)
    .map(({ candidate }) => candidate);
};

const recoverLocator = async (
  plug: SavedBlePlug,
  options: SavedBlePlugLocatorRecoveryOptions,
  scanCandidates: RecoveryScanCandidates,
  inspectCandidate: RecoveryInspectCandidate
): Promise<string> => {
  const canonicalPhysicalId = normalizeShellyDeviceId(plug.physicalId);
  const candidates = prioritizeCandidates(plug, await scanCandidates());

  for (const candidate of candidates) {
    let verified: VerifiedPlugBleCandidate;
    try {
      verified = await inspectCandidate(candidate);
    } catch {
      continue;
    }

    if (normalizeShellyDeviceId(verified.physicalId) !== canonicalPhysicalId) continue;

    options.persistLocator(plug.physicalId, verified.bleDeviceId);
    return verified.bleDeviceId;
  }

  throw new Error('Saved Shelly Plug could not be rediscovered over Bluetooth.');
};

export const recoverSavedBlePlugLocator = (
  plug: SavedBlePlug,
  options: SavedBlePlugLocatorRecoveryOptions,
  dependencies: SavedBlePlugLocatorRecoveryDependencies = {}
): Promise<string> => {
  const key = normalizeShellyDeviceId(plug.physicalId);
  const existing = recoveryByPhysicalId.get(key);
  if (existing) return existing;

  const recovery = recoverLocator(
    plug,
    options,
    dependencies.scanCandidates ?? defaultScanCandidates,
    dependencies.inspectCandidate ?? defaultInspectCandidate
  );
  recoveryByPhysicalId.set(key, recovery);

  const cleanup = () => {
    if (recoveryByPhysicalId.get(key) === recovery) recoveryByPhysicalId.delete(key);
  };
  void recovery.then(cleanup, cleanup);
  return recovery;
};
""")

Path('apps/mobile/src/features/plugs/flows/readSavedBlePlugRuntimeStatus.ts').write_text("""import { isRecoverableBlePlugReadError } from '../data/blePlugReadError.js';
import {
  readBlePlugRuntimeStatus,
  type BlePlugRuntimeStatus
} from '../data/blePlugRuntime.js';
import type { SavedBlePlug } from '../data/savedBlePlug.js';
import {
  recoverSavedBlePlugLocator,
  type SavedBlePlugLocatorRecoveryDependencies,
  type SavedBlePlugLocatorRecoveryOptions
} from './recoverSavedBlePlugLocator.js';

export type SavedBlePlugRuntimeRecoveryOptions = SavedBlePlugLocatorRecoveryOptions;

export type SavedBlePlugRuntimeRecoveryDependencies =
  SavedBlePlugLocatorRecoveryDependencies & {
    readStatus?(plug: Pick<SavedBlePlug, 'bleDeviceId'>): Promise<BlePlugRuntimeStatus>;
  };

export const readSavedBlePlugRuntimeStatus = async (
  plug: SavedBlePlug,
  options: SavedBlePlugRuntimeRecoveryOptions,
  dependencies: SavedBlePlugRuntimeRecoveryDependencies = {}
): Promise<BlePlugRuntimeStatus> => {
  const readStatus = dependencies.readStatus ?? readBlePlugRuntimeStatus;

  try {
    return await readStatus(plug);
  } catch (error) {
    if (!isRecoverableBlePlugReadError(error)) throw error;
  }

  const bleDeviceId = await recoverSavedBlePlugLocator(plug, options, dependencies);
  return readStatus({ bleDeviceId });
};
""")

